    let mut out: Vec<i32> = Vec::new();

    // Copy prefix: indices 0 .. k-1 (0-based), i.e. 0 .. (k-1) exclusive? careful:
    // We must copy indices 0..k-2 inclusive, which is `i < k-1`.
